const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for La Serena, Chile
  const laSerena = ee.Geometry.Point([-71.25, -29.9]);
  const buffer = laSerena.buffer(5000); // 5km buffer around city center

  // 2. Get 2024 year-to-date rainfall (Jan 1 - July 7, 2024)
  const current = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate('2024-01-01', '2024-07-08')
    .filterBounds(buffer);

  const currentSize = current.size().getInfo();
  console.log(`Current year images (2024): ${currentSize}`);

  if (currentSize === 0) {
    console.log("No data available for 2024.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Calculate current year total rainfall
  const currentSum = current.sum();
  const currentRainfall = currentSum.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: buffer,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation');

  const currentVal = currentRainfall.getInfo();

  if (currentVal === null || currentVal === undefined) {
    console.log("Failed to calculate current rainfall.");
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`2024 YTD rainfall (Jan 1 - Jul 7): ${currentVal.toFixed(2)} mm`);

  // 4. Calculate historical mean (1990-2020, same period)
  let historicalSum = 0;
  let yearCount = 0;

  for (let year = 1990; year <= 2020; year++) {
    const historical = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
      .filterDate(`${year}-01-01`, `${year}-07-08`)
      .filterBounds(buffer);

    const histSize = historical.size().getInfo();

    if (histSize > 0) {
      const histSum = historical.sum();
      const histRainfall = histSum.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: buffer,
        scale: 5000,
        maxPixels: 1e9
      }).get('precipitation');

      const histVal = histRainfall.getInfo();

      if (histVal !== null && histVal !== undefined) {
        historicalSum += histVal;
        yearCount++;
      }
    }
  }

  if (yearCount === 0) {
    console.log("No historical data available.");
    console.log("<answer>C1</answer>");
    return;
  }

  const historicalMean = historicalSum / yearCount;
  console.log(`Historical mean (1990-2020): ${historicalMean.toFixed(2)} mm (${yearCount} years)`);

  // 5. Calculate deficit percentage
  const deficit = ((historicalMean - currentVal) / historicalMean) * 100;
  console.log(`Deficit: ${deficit.toFixed(1)}%`);

  // 6. Determine answer
  if (deficit > 40) {
    console.log(`Deficit of ${deficit.toFixed(1)}% is greater than 40%.`);
    console.log("<answer>A</answer>");
  } else {
    console.log(`Deficit of ${deficit.toFixed(1)}% is not greater than 40%.`);
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
